settings.liquid:
{% if product %}
  {% assign sub = product.metafields.descriptors.subtitle 
    | default: "Moves like second skin, shapes every curve." %}

  <div class="cf-mech-block">
    <div class="cf-mech-head">CURVEFLEX™ 4-WAY DENIM</div>
    <div class="cf-mech-sub">{{ sub }}</div>
  </div>

  <style>
    .cf-mech-block{ margin:6px 0 10px; }
    .cf-mech-head{
      font-size:13px;
      font-weight:600;
      letter-spacing:.05em;
      text-transform:uppercase;
      color:#6c6d70;     /* muted grey for premium tone */
      margin-bottom:2px;
    }
    .cf-mech-sub{
      font-size:14px;
      line-height:1.45;
      color:#111;
      font-weight:400;
    }
    @media (min-width:768px){
      .cf-mech-head{ font-size:14px; }
      .cf-mech-sub{ font-size:15px; }
    }
  </style>
{% endif %}

{%- comment -%}
CURVJEANS — JEANS “Stretchiness” row (Impact-style accordion header)
Data (metaobject refs via .value; handle-first; supports list or single):
  • Stretchiness (ONE) : product.metafields.custom.stretch_level.value
  • Rise               : product.metafields.shopify['waist-rise'].value
  • Fit                : product.metafields.shopify.fit.value
  • Length             : product.metafields.shopify['pants-length-type'].value
  • Optional Length override: product.metafields.custom.length_text
Behavior:
  • Default open (set data-open="false" to start closed)
  • Bars: Comfort=3/5, Mega/4-Way=5/5
{%- endcomment -%}

{%- assign _lc = localization.language.iso_code | default: shop.locale | default: 'EN' | upcase -%}
{%- if _lc == 'NL' -%}
  {%- assign t_head='Stretchiness' -%}
  {%- assign t_comfort='Comfort Stretch' -%}{%- assign t_mega='Mega Stretch' -%}
  {%- assign t_rise_low='Low Rise' -%}{%- assign t_rise_mid='Mid Rise' -%}{%- assign t_rise_high='Hoge taille' -%}
  {%- assign t_fit_snug='Snug (twijfel? Neem 1 maat groter)' -%}
  {%- assign t_fit_tts='Valt op maat' -%}
  {%- assign t_fit_relaxed='Relaxed fit' -%}
{%- elsif _lc == 'DE' -%}
  {%- assign t_head='Stretchiness' -%}
  {%- assign t_comfort='Comfort Stretch' -%}{%- assign t_mega='Mega Stretch' -%}
  {%- assign t_rise_low='Low Rise' -%}{%- assign t_rise_mid='Mid Rise' -%}{%- assign t_rise_high='Hohe Taille' -%}
  {%- assign t_fit_snug='Snug (wenn zwischen Größen, eine größer nehmen)' -%}
  {%- assign t_fit_tts='Fällt normal aus' -%}
  {%- assign t_fit_relaxed='Relaxed Fit' -%}
{%- else -%}
  {%- assign t_head='Stretchiness' -%}
  {%- assign t_comfort='Comfort Stretch' -%}{%- assign t_mega='Mega Stretch' -%}
  {%- assign t_rise_low='Low Rise' -%}{%- assign t_rise_mid='Mid Rise' -%}{%- assign t_rise_high='High Waist' -%}
  {%- assign t_fit_snug='Snug (size up if in between)' -%}
  {%- assign t_fit_tts='True to size' -%}
  {%- assign t_fit_relaxed='Relaxed fit' -%}
{%- endif -%}

{%- comment -%} --- READ METAOBJECTS --- {%- endcomment -%}
{%- assign stretch_obj = product.metafields.custom.stretch_level.value -%}
{%- assign stretch_label = stretch_obj.label | default: stretch_obj.title | default: stretch_obj.name | default: stretch_obj.handle | default: stretch_obj | strip -%}

{%- assign rise_val = product.metafields.shopify['waist-rise'].value -%}
{%- assign rise_json = rise_val | json -%}
{%- assign rise_entry = rise_val -%}{% if rise_val and rise_json contains '[' %}{%- assign rise_entry = rise_val | first -%}{% endif %}
{%- assign r_handle = rise_entry.handle | default: '' | downcase -%}
{%- assign r_label  = rise_entry.label  | default: rise_entry.title | default: rise_entry.name | default: rise_entry | downcase -%}

{%- assign fit_val = product.metafields.shopify.fit.value -%}
{%- assign fit_json = fit_val | json -%}
{%- assign fit_entry = fit_val -%}{% if fit_val and fit_json contains '[' %}{%- assign fit_entry = fit_val | first -%}{% endif %}
{%- assign f_handle = fit_entry.handle | default: '' | downcase -%}
{%- assign f_label  = fit_entry.label  | default: fit_entry.title | default: fit_entry.name | default: fit_entry | downcase -%}

{%- assign length_val = product.metafields.shopify['pants-length-type'].value -%}
{%- assign length_json = length_val | json -%}
{%- assign length_entry = length_val -%}{% if length_val and length_json contains '[' %}{%- assign length_entry = length_val | first -%}{% endif %}
{%- assign l_label  = length_entry.label  | default: length_entry.title | default: length_entry.name | default: length_entry | strip -%}

{%- assign length_override = product.metafields.custom.length_text | default: '' -%}

{%- comment -%} --- MAP VALUES --- {%- endcomment -%}
{%- assign stretch_text = t_comfort -%}{%- assign stretch_bars = 3 -%}
{%- assign sl = stretch_label | downcase -%}
{%- if sl contains 'mega' or sl contains '4-way' or sl contains '4 way' or sl contains 'super' -%}
  {%- assign stretch_text = t_mega -%}{%- assign stretch_bars = 5 -%}
{%- endif -%}

{%- assign rise_text = t_rise_mid -%}
{%- if r_handle contains 'high' or r_label contains 'high' or r_label contains 'hoch' or r_label contains 'hoog' -%}
  {%- assign rise_text = t_rise_high -%}
{%- elsif r_handle contains 'low' or r_label contains 'low' or r_label contains 'laag' or r_label contains 'niedrig' -%}
  {%- assign rise_text = t_rise_low -%}
{%- endif -%}

{%- assign fit_text = t_fit_tts -%}
{%- if f_handle contains 'slim' or f_handle contains 'snug' or f_handle contains 'straight' or f_label contains 'slim' or f_label contains 'snug' or f_label contains 'straight' -%}
  {%- assign fit_text = t_fit_snug -%}
{%- elsif f_handle contains 'relax' or f_handle contains 'wide' or f_handle contains 'easy' or f_handle contains 'regular' or f_label contains 'relax' or f_label contains 'wide' or f_label contains 'easy' or f_label contains 'regular' -%}
  {%- assign fit_text = t_fit_relaxed -%}
{%- endif -%}

{%- assign length_text = length_override | strip | default: l_label -%}
{%- case _lc -%}
  {%- when 'NL' -%}{%- assign length_text = length_text | replace: 'Up to', 'Tot' | replace: 'up to', 'tot' | replace: 'UP TO', 'TOT' -%}
  {%- when 'DE' -%}{%- assign length_text = length_text | replace: 'Up to', 'Bis' | replace: 'up to', 'bis' | replace: 'UP TO', 'BIS' -%}
{%- endcase -%}

<style>
  :root{
    --curv-border: rgba(17,17,17,.08);
    --row-pad-y: 14px;      /* auto-synced to theme via JS below */
    --chev-size: 24px;
    --chev-icon: 10px;
  }
  .cj-jeans-acc{ color:#000; margin:16px 0 0; border-top:1px solid var(--curv-border); }
  .cj-jeans-acc__head{
    display:flex; align-items:center; justify-content:space-between;
    padding:var(--row-pad-y) 0; line-height:1;
  }
  .cj-jeans-acc__title{ font-weight:700; color:#000; }

  /* Impact-like chevron button */
  .cj-jeans-acc__chevbtn{
    width:var(--chev-size); height:var(--chev-size);
    border-radius:999px; background:#EDEDED;
    display:inline-flex; align-items:center; justify-content:center;
    flex:0 0 auto;
  }
  .cj-jeans-acc__chev{
    width:var(--chev-icon); height:var(--chev-icon);
    stroke:#000; stroke-width:2.6; stroke-linecap:round; stroke-linejoin:round; fill:none;
    transition:transform .2s ease;
  }
  .cj-jeans-acc.is-open .cj-jeans-acc__chev{ transform:rotate(180deg); }

  /* Panel — zero space when closed */
  .cj-jeans-acc__panel[hidden]{ display:none !important; }
  .cj-jeans-acc__panel{ padding:0 0 12px; }

  /* Bars (black, minimal) */
  .cj-bars{ display:inline-flex; align-items:flex-end; gap:3px; height:14px; margin-right:.5rem; }
  .cj-bar{ width:3px; background:#e5e7eb; border-radius:2px; }
  .cj-bar:nth-child(1){ height:5px } .cj-bar:nth-child(2){ height:7px }
  .cj-bar:nth-child(3){ height:9px } .cj-bar:nth-child(4){ height:11px }
  .cj-bar:nth-child(5){ height:13px }
  .cj-bar.is-on{ background:#000; }

  .cj-line{ display:flex; align-items:center; gap:.5rem; margin:0 0 6px; }
  .cj-level{ font-weight:600; color:#000; }

  /* Inline meta: Rise • Fit • Length */
  .cj-meta{ display:flex; flex-wrap:wrap; align-items:center; gap:10px; margin:4px 0 0; color:#000; }
  .cj-dot{ opacity:.35; margin:0 2px; }
</style>

<section class="cj-jeans-acc is-open" id="cj-jeans-acc" data-open="true" role="group" aria-label="{{ t_head }}">
  <div class="cj-jeans-acc__head" role="button" tabindex="0" aria-controls="cj-jeans-panel" aria-expanded="true">
    <span class="cj-jeans-acc__title">{{ t_head }}</span>
    <span class="cj-jeans-acc__chevbtn" aria-hidden="true">
      <svg class="cj-jeans-acc__chev" viewBox="0 0 20 20"><path d="M5 8l5 5 5-5"/></svg>
    </span>
  </div>

  <div class="cj-jeans-acc__panel" id="cj-jeans-panel">
    <div class="cj-line">
      <span class="cj-bars" role="img" aria-label="{{ stretch_text }}">
        {%- for i in (1..5) -%}<span class="cj-bar{% if i <= stretch_bars %} is-on{% endif %}"></span>{%- endfor -%}
      </span>
      <span class="cj-level">{{ stretch_text }}</span>
    </div>

    <div class="cj-meta">
      <span>{{ rise_text }}</span>
      <span class="cj-dot" aria-hidden="true">•</span>
      <span>{{ fit_text }}</span>
      <span class="cj-dot" aria-hidden="true">•</span>
      <span>{{ length_text }}</span>
    </div>
  </div>
</section>

<script>
(function(){
  var root = document.getElementById('cj-jeans-acc');
  if(!root) return;

  var head = root.querySelector('.cj-jeans-acc__head');
  var panel = root.querySelector('.cj-jeans-acc__panel');
  var startOpen = (root.getAttribute('data-open') || 'true') === 'true';

  function setOpen(open){
    root.classList.toggle('is-open', open);
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    if(open){ panel.removeAttribute('hidden'); } else { panel.setAttribute('hidden',''); }
  }
  setOpen(startOpen);

  head.addEventListener('click', function(){ setOpen(!root.classList.contains('is-open')); });
  head.addEventListener('keydown', function(e){
    if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); head.click(); }
  });

  /* Auto-sync our row padding with Impact’s accordion rows so the title aligns perfectly */
  var ref = document.querySelector('.product-info__accordion .accordion__toggle, details.product-info__accordion .accordion__toggle');
  if (ref) {
    var cs = getComputedStyle(ref);
    var py = parseFloat(cs.paddingTop) || 16;
    root.style.setProperty('--row-pad-y', py + 'px');
  }

  /* Seam: remove the top gap of the next accordion group via inline style (no theme edits) */
  var next = root.nextElementSibling;
  if (next && next.matches('.product-info__block-group.accordion-group[data-group-type="accordion-group"]')) {
    next.style.setProperty('margin-top','0','important');
    next.style.setProperty('margin-block-start','0','important');
  }

  /* Also kill any residual top margin on our own block */
  root.style.marginTop = '0';
})();
</script>
